msg.topic = 'SELECT id, cell_count FROM trucks';
msg.payload = [];
return msg;

// Store the valid truck ids (and their expected cell count) in GLOBAL context
// so every validate node can check against them without hitting the DB.
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const map = {};
for (const r of rows) map[r.id] = { cell_count: r.cell_count };
global.set('knownTrucks', map);
node.status({ fill: 'green', shape: 'dot', text: rows.length + ' trucks cached' });
return null;

const id = (msg.topic || '').split('/')[1];
const p = msg.payload;
const bad = (reason) => ({ payload: { truck_id: id || null, topic: msg.topic, reason, raw: p } });

if (!id) return [null, bad('empty truck id in topic')];
if (!p || typeof p !== 'object' || Array.isArray(p)) return [null, bad('payload is not a JSON object')];
if (typeof p.online !== 'boolean') return [null, bad('online must be true or false')];

const known = global.get('knownTrucks') || {};
if (Object.keys(known).length && !known[id]) return [null, bad('unknown truck id: ' + id)];

return [msg, null];

const id = msg.topic.split('/')[1];
const p = msg.payload;
msg.topic = 'INSERT INTO truck_status (truck_id, online, last_seen) VALUES (?, ?, NOW()) ON DUPLICATE KEY UPDATE online=VALUES(online), last_seen=NOW()';
msg.payload = [id, p.online ? 1 : 0];
return msg;

const id = (msg.topic || '').split('/')[1];
const p = msg.payload;
const TEST_MODE = flow.get('testMode') === true;   // ← flag คุม temporal
const bad = (reason) => ({ payload: { truck_id: id || null, topic: msg.topic, reason, raw: p } });
const num = (v) => typeof v === 'number' && isFinite(v);

// --- structural (เก็บเสมอ แม้ TEST_MODE) ---
if (!id) return [null, bad('empty truck id in topic')];
if (!p || typeof p !== 'object' || Array.isArray(p)) return [null, bad('payload is not a JSON object')];
const known = global.get('knownTrucks') || {};
if (Object.keys(known).length && !known[id]) return [null, bad('unknown truck id: ' + id)];

// --- range / plausibility (เก็บเสมอ) ---
if (!num(p.lat) || !num(p.lng)) return [null, bad('lat/lng missing or not numeric')];
if (p.lat < -90 || p.lat > 90 || p.lng < -180 || p.lng > 180) return [null, bad('lat/lng out of valid range')];
if (p.lat === 0 && p.lng === 0) return [null, bad('GPS has no fix (0,0)')];
if (!num(p.speedKph) || p.speedKph < 0 || p.speedKph > 120) return [null, bad('speedKph out of range 0-120: ' + p.speedKph)];
if (!num(p.odometerKm) || p.odometerKm < 0) return [null, bad('odometerKm missing or negative')];
if (!num(p.tripKm) || p.tripKm < 0) return [null, bad('tripKm missing or negative')];
if (!num(p.motorTempC) || p.motorTempC < -40 || p.motorTempC > 150) return [null, bad('motorTempC out of range -40..150: ' + p.motorTempC)];

// --- temporal (ข้ามทั้งหมดถ้า TEST_MODE) ---
const now = Date.now();
const prev = flow.get('last_tel_' + id);
if (prev && !TEST_MODE) {
  const dt = Math.max(0.001, (now - prev.t) / 1000);
  if (p.odometerKm < prev.odo - 0.01) return [null, bad('odometer went backwards: ' + prev.odo + ' -> ' + p.odometerKm)];
  if ((p.odometerKm - prev.odo) / dt * 3600 > 200) return [null, bad('odometer jump implies >200 km/h')];
  const dLat = (p.lat - prev.lat) * 111;
  const dLng = (p.lng - prev.lng) * 111 * Math.cos(p.lat * Math.PI / 180);
  const km = Math.sqrt(dLat * dLat + dLng * dLng);
  if (km / dt * 3600 > 200) return [null, bad('GPS teleport: ' + km.toFixed(2) + ' km in ' + dt.toFixed(1) + 's')];
}
flow.set('last_tel_' + id, { t: now, odo: p.odometerKm, lat: p.lat, lng: p.lng });

// แสดง badge เตือนถ้า TEST_MODE เปิด
node.status(TEST_MODE
  ? { fill: 'yellow', shape: 'dot', text: 'TEST_MODE — temporal checks OFF' }
  : {});

return [msg, null];

const id = msg.topic.split('/')[1];
const p = msg.payload;
msg.topic = 'INSERT INTO truck_status (truck_id, online, last_seen, lat, lng, speed_kph, odometer_km, trip_km, motor_temp_c) VALUES (?, TRUE, NOW(), ?, ?, ?, ?, ?, ?) ON DUPLICATE KEY UPDATE online=TRUE, last_seen=NOW(), lat=VALUES(lat), lng=VALUES(lng), speed_kph=VALUES(speed_kph), odometer_km=VALUES(odometer_km), trip_km=VALUES(trip_km), motor_temp_c=VALUES(motor_temp_c)';
msg.payload = [id, p.lat, p.lng, p.speedKph, p.odometerKm, p.tripKm, p.motorTempC];
return msg;

const id = (msg.topic || '').split('/')[1];
const p = msg.payload;
const bad = (reason) => ({ payload: { truck_id: id || null, topic: msg.topic, reason, raw: p } });
const num = (v) => typeof v === 'number' && isFinite(v);

// --- structural -----------------------------------------------------------
if (!id) return [null, bad('empty truck id in topic')];
if (!p || typeof p !== 'object' || Array.isArray(p)) return [null, bad('payload is not a JSON object')];
const known = global.get('knownTrucks') || {};
if (Object.keys(known).length && !known[id]) return [null, bad('unknown truck id: ' + id)];

if (!Array.isArray(p.cells) || p.cells.length === 0) return [null, bad('cells missing or empty')];
if (p.cells.length > 64) return [null, bad('implausible cell count: ' + p.cells.length)];
const expect = known[id] && known[id].cell_count;
if (expect && p.cells.length !== expect) return [null, bad('cell count ' + p.cells.length + ' != expected ' + expect)];

// --- per-cell range checks ------------------------------------------------
// A cell outside these bounds is a SENSOR FAULT, not a flat battery — a real
// Li-ion cell never reads 9.9V or 114C. Reject the whole message so one bad
// sensor can't poison the pack stats.
for (const c of p.cells) {
  if (!c || typeof c !== 'object') return [null, bad('cells contains a non-object entry')];
  if (!num(c.voltage) || c.voltage < 2.5 || c.voltage > 4.3) return [null, bad('cell ' + c.id + ' voltage out of range 2.5-4.3: ' + c.voltage)];
  if (!num(c.tempC) || c.tempC < -20 || c.tempC > 80) return [null, bad('cell ' + c.id + ' temp out of range -20..80: ' + c.tempC)];
}

// --- pack-level checks ----------------------------------------------------
if (!num(p.totalPct) || p.totalPct < 0 || p.totalPct > 100) return [null, bad('totalPct out of range 0-100: ' + p.totalPct)];
if (!num(p.packVoltage) || p.packVoltage <= 0) return [null, bad('packVoltage missing or <= 0')];
if (!num(p.packCurrentA)) return [null, bad('packCurrentA missing or not numeric')];
if (p.rangeKm !== undefined && (!num(p.rangeKm) || p.rangeKm < 0)) return [null, bad('rangeKm negative')];

return [msg, null];

const id = msg.topic.split('/')[1];
const p = msg.payload;
const cells = p.cells;
const volts = cells.map(c => c.voltage);
const temps = cells.map(c => c.tempC);
const deltaMv = Math.round((Math.max.apply(null, volts) - Math.min.apply(null, volts)) * 1000);
const maxTemp = Math.max.apply(null, temps);

const up = {
  topic: 'INSERT INTO truck_status (truck_id, online, last_seen, pack_voltage, pack_current_a, total_pct, range_km, cells_json, delta_mv, max_temp_c) VALUES (?, TRUE, NOW(), ?, ?, ?, ?, ?, ?, ?) ON DUPLICATE KEY UPDATE online=TRUE, last_seen=NOW(), pack_voltage=VALUES(pack_voltage), pack_current_a=VALUES(pack_current_a), total_pct=VALUES(total_pct), range_km=VALUES(range_km), cells_json=VALUES(cells_json), delta_mv=VALUES(delta_mv), max_temp_c=VALUES(max_temp_c)',
  payload: [id, p.packVoltage, p.packCurrentA, p.totalPct, p.rangeKm === undefined ? null : p.rangeKm, JSON.stringify(cells), deltaMv, maxTemp]
};

// Alerts are about REAL conditions now — the validator already threw out
// impossible readings, so anything that fires here is worth acting on.
let a = null;
if (maxTemp > 50) a = { type: 'over_temp', sev: 'critical', msg: 'Max cell temp ' + maxTemp + 'C' };
else if (deltaMv > 150) a = { type: 'cell_delta_high', sev: 'warning', msg: 'Cell delta ' + deltaMv + ' mV' };
else if (p.totalPct < 15) a = { type: 'low_soc', sev: 'warning', msg: 'SOC ' + p.totalPct + '%' };

// Only raise an alert when the condition CHANGES, so we don't insert a row
// every 2 seconds for the same ongoing fault.
const prev = flow.get('lastAlert_' + id) || null;
const nowKey = a ? a.type : 'none';
flow.set('lastAlert_' + id, nowKey);
const alertMsg = (a && prev !== nowKey) ? {
  topic: 'INSERT INTO alerts (truck_id, ts, type, severity, message) VALUES (?, NOW(3), ?, ?, ?)',
  payload: [id, a.type, a.sev, a.msg]
} : null;

return [up, alertMsg];

const id = (msg.topic || '').split('/')[1];
const p = msg.payload;
const bad = (reason) => ({ payload: { truck_id: id || null, topic: msg.topic, reason, raw: p } });
const SEV = ['info', 'warning', 'critical'];

if (!id) return [null, bad('empty truck id in topic')];
if (!p || typeof p !== 'object' || Array.isArray(p)) return [null, bad('payload is not a JSON object')];
const known = global.get('knownTrucks') || {};
if (Object.keys(known).length && !known[id]) return [null, bad('unknown truck id: ' + id)];
if (typeof p.type !== 'string' || !p.type.trim()) return [null, bad('alert type missing')];
if (p.severity !== undefined && !SEV.includes(p.severity)) return [null, bad('severity must be info|warning|critical')];

return [msg, null];

const id = msg.topic.split('/')[1];
const p = msg.payload;
msg.topic = 'INSERT INTO alerts (truck_id, ts, type, severity, message) VALUES (?, NOW(3), ?, ?, ?)';
msg.payload = [id, p.type.substring(0, 32), p.severity || 'info', p.message ? String(p.message).substring(0, 255) : null];
return msg;

// Every validate node's SECOND output lands here. We store why the message
// was refused, plus the raw payload, so a broken sensor is VISIBLE rather
// than silently dropped.
const p = msg.payload || {};
const reason = String(p.reason || 'unknown');

// Count rejects on the node's status badge for quick visual feedback.
const n = (flow.get('rejectCount') || 0) + 1;
flow.set('rejectCount', n);
node.status({ fill: 'red', shape: 'ring', text: n + ' rejected — ' + reason.substring(0, 40) });

msg.topic = 'INSERT INTO rejects (truck_id, topic, reason, payload) VALUES (?, ?, ?, ?)';
msg.payload = [
  p.truck_id || null,
  p.topic ? String(p.topic).substring(0, 128) : null,
  reason.substring(0, 255),
  JSON.stringify(p.raw === undefined ? null : p.raw)
];
return msg;

// Read the live rows, then let the next node decide which are worth keeping.
msg.topic = 'SELECT truck_id, lat, lng, speed_kph, odometer_km, motor_temp_c, pack_voltage, pack_current_a, total_pct, cells_json, delta_mv, max_temp_c FROM truck_status WHERE online = TRUE';
msg.payload = [];
return msg;

// REPORT BY EXCEPTION: only write a history row when something meaningful
// changed, OR the heartbeat expired. A parked truck therefore produces one
// row a minute instead of one every 5 seconds.
//
// NOTE: this only filters the HISTORY table. truck_status (the live row the
// dashboard reads) is still updated by every MQTT message, so last_seen keeps
// moving and a parked truck never looks offline.

// --- tune these ---------------------------------------------------------
const MOVE_KM = 0.005;   // 5 metres of odometer travel counts as "moved"
const SOC_STEP = 1;      // battery % change worth recording
const HEARTBEAT_MS = 60000; // always store at least one row per truck per minute
// ------------------------------------------------------------------------

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const now = Date.now();
const out = [];
let skipped = 0;

for (const s of rows) {
  const prev = flow.get('lastHist_' + s.truck_id);

  const moved = !prev || (s.odometer_km - prev.odo) > MOVE_KM;
  const socChanged = !prev || Math.abs((s.total_pct || 0) - (prev.pct || 0)) >= SOC_STEP;
  const stale = !prev || (now - prev.t) > HEARTBEAT_MS;

  if (!moved && !socChanged && !stale) {
    skipped++;
    continue; // idle and nothing changed — don't store
  }

  flow.set('lastHist_' + s.truck_id, { t: now, odo: s.odometer_km, pct: s.total_pct });

  // the driver returns JSON columns already parsed, so re-stringify if needed
  const cells = (typeof s.cells_json === 'string' || s.cells_json === null)
    ? s.cells_json
    : JSON.stringify(s.cells_json);

  out.push({
    topic: 'INSERT INTO telemetry (truck_id, ts, lat, lng, speed_kph, odometer_km, motor_temp_c, pack_voltage, pack_current_a, total_pct, cells_json, delta_mv, max_temp_c) VALUES (?, NOW(3), ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    payload: [s.truck_id, s.lat, s.lng, s.speed_kph, s.odometer_km, s.motor_temp_c, s.pack_voltage, s.pack_current_a, s.total_pct, cells, s.delta_mv, s.max_temp_c]
  });
}

node.status({ fill: 'blue', shape: 'dot', text: out.length + ' stored, ' + skipped + ' idle-skipped' });
return [out];

// Physically plausible simulation: values are DERIVED from a state-of-charge
// that drains and recharges, instead of a free random walk that runs away.
const ids = ['CMT-01', 'CMT-02', 'CMT-03'];
const base = { 'CMT-01': [13.7563, 100.5018], 'CMT-02': [13.7469, 100.5349], 'CMT-03': [13.7231, 100.5150] };
const rnd = (a, b) => a + Math.random() * (b - a);
const r = (v, d) => +v.toFixed(d);
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const msgs = [];

for (const id of ids) {
  let s = flow.get('sim_' + id);
  if (!s) {
    s = { lat: base[id][0], lng: base[id][1], speed: 0, odo: 48000 + Math.random() * 500, trip: 0, motor: 38, soc: rnd(55, 95), off: [] };
    // a fixed per-cell offset gives each pack a realistic, stable spread
    for (let i = 0; i < 12; i++) s.off.push(rnd(-0.02, 0.02));
  }

  // speed: bounded random walk; position wanders near the depot
  s.speed = clamp(s.speed + rnd(-8, 9), 0, 90);
  const stepKm = s.speed / 3600 * 2; // 2-second tick
  s.odo += stepKm;
  s.trip += stepKm;
  s.lat = clamp(s.lat + rnd(-0.0006, 0.0006), base[id][0] - 0.05, base[id][0] + 0.05);
  s.lng = clamp(s.lng + rnd(-0.0006, 0.0006), base[id][1] - 0.05, base[id][1] + 0.05);

  // motor temp drifts TOWARD a target set by speed (mean reversion, no runaway)
  const motorTarget = 35 + s.speed / 3;
  s.motor = clamp(s.motor + (motorTarget - s.motor) * 0.05 + rnd(-0.3, 0.3), 25, 95);

  // state of charge: drains with speed, jumps back up at the depot when low
  s.soc -= (0.02 + s.speed / 9000);
  if (s.soc <= 20) s.soc = 95;
  const socV = 3.35 + (s.soc / 100) * 0.8; // ~3.35V low .. 4.15V full

  const cells = [];
  let sumV = 0, sumPct = 0;
  for (let i = 0; i < 12; i++) {
    const v = r(clamp(socV + s.off[i] + rnd(-0.004, 0.004), 3.0, 4.2), 3);
    const t = r(clamp(30 + s.speed / 6 + s.off[i] * 100 + rnd(-1, 1), 20, 48), 1);
    const pct = Math.round(clamp((v - 3.0) / 1.2 * 100, 0, 100));
    cells.push({ id: i + 1, voltage: v, tempC: t, pct });
    sumV += v;
    sumPct += pct;
  }
  const totalPct = Math.round(sumPct / cells.length);
  flow.set('sim_' + id, s);

  msgs.push({
    topic: 'cmt/' + id + '/telemetry',
    payload: { lat: r(s.lat, 6), lng: r(s.lng, 6), speedKph: Math.round(s.speed), odometerKm: r(s.odo, 3), tripKm: r(s.trip, 3), motorTempC: Math.round(s.motor) }
  });
  msgs.push({
    topic: 'cmt/' + id + '/battery',
    payload: { packVoltage: r(sumV, 1), packCurrentA: r(rnd(-40, 120), 1), totalPct, rangeKm: Math.round(totalPct * 2.1), cells },
    retain: true
  });
}
return [msgs];

// Each of these trips a DIFFERENT guard — watch them appear in the
// 'rejected' debug panel and in the cmt.rejects table.
return [[
  // 1. GPS with no fix reports 0,0 ("Null Island")
  { topic: 'cmt/CMT-01/telemetry', payload: { lat: 0, lng: 0, speedKph: 20, odometerKm: 48100, tripKm: 5, motorTempC: 40 } },
  // 2. impossible cell readings (the bug that got through before)
  { topic: 'cmt/CMT-02/battery', payload: { packVoltage: 44, packCurrentA: 10, totalPct: 60, rangeKm: 120, cells: [{ id: 1, voltage: 9.9, tempC: 114.6, pct: 0 }] } },
  // 3. a truck that isn't in the trucks table
  { topic: 'cmt/CMT-99/telemetry', payload: { lat: 13.75, lng: 100.5, speedKph: 20, odometerKm: 10, tripKm: 1, motorTempC: 40 } },
  // 4. speed a loaded cement truck cannot reach
  { topic: 'cmt/CMT-03/telemetry', payload: { lat: 13.72, lng: 100.51, speedKph: 480, odometerKm: 34000, tripKm: 2, motorTempC: 40 } }
]];
